import{_ as e,o as r,c as l,a2 as t}from"./chunks/framework.BXzK3EA4.js";const R=JSON.parse('{"title":"이동과 조우 규칙","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Rules-TravelEncounters.md","filePath":"rules/Rules-TravelEncounters.md"}'),i={name:"rules/Rules-TravelEncounters.md"};function o(h,a,d,n,s,c){return r(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="이동과-조우-규칙" tabindex="-1">이동과 조우 규칙 <a class="header-anchor" href="#이동과-조우-규칙" aria-label="Permalink to &quot;이동과 조우 규칙&quot;">​</a></h1><blockquote><p>출처: docs/game-logic/Travel-and-Encounters.md — 계약 수치는 구현 상수를 우선한다.</p></blockquote><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>원정 이동은 동서남북 네 방향만 받는다. 조우의 확률과 유형은 위치와 방향과 시야로 가른다. 탐색과 전투가 같은 격자를 쓰므로 거리 판단은 전장을 오가도 흔들리지 않는다.</p><h2 id="핵심-수치" tabindex="-1">핵심 수치 <a class="header-anchor" href="#핵심-수치" aria-label="Permalink to &quot;핵심 수치&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>값</th><th>비고</th></tr></thead><tbody><tr><td>허용 방향</td><td>4</td><td>동 서 남 북</td></tr><tr><td>기본 이동 단위</td><td>한 칸</td><td>조건 비용을 더한다</td></tr><tr><td>대각선 입력</td><td>거부</td><td>행동을 소비하지 않는다</td></tr><tr><td>조우 재현</td><td>동일 상태와 동일 명령</td><td>같은 조우가 나와야 한다</td></tr><tr><td>격자</td><td>탐색과 전투가 동일</td><td>거리 감각을 바꾸지 않는다</td></tr></tbody></table><p>원문은 칸당 숫자 비용과 조우 확률표를 적지 않았다. 구현 상수가 있으면 그 값을 따른다.</p><h2 id="조항" tabindex="-1">조항 <a class="header-anchor" href="#조항" aria-label="Permalink to &quot;조항&quot;">​</a></h2><h3 id="rtravel-01-네-방향만-허용" tabindex="-1">RTRAVEL-01 네 방향만 허용 <a class="header-anchor" href="#rtravel-01-네-방향만-허용" aria-label="Permalink to &quot;RTRAVEL-01 네 방향만 허용&quot;">​</a></h3><p>이동 입력은 동과 서와 남과 북뿐이다. 다른 방위는 이동으로 치지 않는다.</p><h3 id="rtravel-02-대각선-입력-거부" tabindex="-1">RTRAVEL-02 대각선 입력 거부 <a class="header-anchor" href="#rtravel-02-대각선-입력-거부" aria-label="Permalink to &quot;RTRAVEL-02 대각선 입력 거부&quot;">​</a></h3><p>대각선 입력은 즉시 거부한다. 이 거부는 행동을 깎지 않는다.</p><h3 id="rtravel-03-동일-격자" tabindex="-1">RTRAVEL-03 동일 격자 <a class="header-anchor" href="#rtravel-03-동일-격자" aria-label="Permalink to &quot;RTRAVEL-03 동일 격자&quot;">​</a></h3><p>탐색과 전투는 같은 격자를 쓴다. 칸을 세는 감각은 전장을 오가도 유지된다.</p><h3 id="rtravel-04-조우-판정-축" tabindex="-1">RTRAVEL-04 조우 판정 축 <a class="header-anchor" href="#rtravel-04-조우-판정-축" aria-label="Permalink to &quot;RTRAVEL-04 조우 판정 축&quot;">​</a></h3><p>조우 확률과 유형은 위치와 방향과 시야로 가른다. 세 축을 빼면 조우를 열지 못한다.</p><h3 id="rtravel-05-기본-칸-비용" tabindex="-1">RTRAVEL-05 기본 칸 비용 <a class="header-anchor" href="#rtravel-05-기본-칸-비용" aria-label="Permalink to &quot;RTRAVEL-05 기본 칸 비용&quot;">​</a></h3><p>한 칸 이동의 기본 비용이 먼저 붙는다. 그다음 조건 비용을 더한다.</p><h3 id="rtravel-06-층-전환" tabindex="-1">RTRAVEL-06 층 전환 <a class="header-anchor" href="#rtravel-06-층-전환" aria-label="Permalink to &quot;RTRAVEL-06 층 전환&quot;">​</a></h3><p>계단과 사다리와 승강기는 층 전환이다. 층 전환은 기본 칸 비용 위에 더한다.</p><h3 id="rtravel-07-몸-상태와-과적" tabindex="-1">RTRAVEL-07 몸 상태와 과적 <a class="header-anchor" href="#rtravel-07-몸-상태와-과적" aria-label="Permalink to &quot;RTRAVEL-07 몸 상태와 과적&quot;">​</a></h3><p>부상과 통증과 피로와 과적은 비용을 불린다. 빠진 항목 없이 모두 더한다.</p><h3 id="rtravel-08-지형-위험" tabindex="-1">RTRAVEL-08 지형 위험 <a class="header-anchor" href="#rtravel-08-지형-위험" aria-label="Permalink to &quot;RTRAVEL-08 지형 위험&quot;">​</a></h3><p>어둠과 침수와 잔해와 화재는 칸 비용을 불린다. 위험 지형은 공짜로 지나가지 못한다.</p><h3 id="rtravel-09-세력-통과" tabindex="-1">RTRAVEL-09 세력 통과 <a class="header-anchor" href="#rtravel-09-세력-통과" aria-label="Permalink to &quot;RTRAVEL-09 세력 통과&quot;">​</a></h3><p>적대 세력의 통제와 통행권도 비용에 넣는다. 통행권이 없으면 그 칸은 값비싼 통과가 된다.</p><h3 id="rtravel-10-편성-부담" tabindex="-1">RTRAVEL-10 편성 부담 <a class="header-anchor" href="#rtravel-10-편성-부담" aria-label="Permalink to &quot;RTRAVEL-10 편성 부담&quot;">​</a></h3><p>파티 규모와 은밀 이동과 호위 대상은 비용을 더한다. 은밀 이동은 무료가 아니다.</p><h3 id="rtravel-11-세계-지도-비교" tabindex="-1">RTRAVEL-11 세계 지도 비교 <a class="header-anchor" href="#rtravel-11-세계-지도-비교" aria-label="Permalink to &quot;RTRAVEL-11 세계 지도 비교&quot;">​</a></h3><p>세계 지도에서는 노선과 환승과 봉쇄를 견준다. 짧은 선이 곧 안전한 선은 아니다.</p><h3 id="rtravel-12-역에서-격자-전개" tabindex="-1">RTRAVEL-12 역에서 격자 전개 <a class="header-anchor" href="#rtravel-12-역에서-격자-전개" aria-label="Permalink to &quot;RTRAVEL-12 역에서 격자 전개&quot;">​</a></h3><p>역을 고르면 같은 세계 그래프에서 세부 격자를 펼친다. 지도와 격자가 다른 세계를 가리키면 안 된다.</p><h3 id="rtravel-13-봉쇄-보존" tabindex="-1">RTRAVEL-13 봉쇄 보존 <a class="header-anchor" href="#rtravel-13-봉쇄-보존" aria-label="Permalink to &quot;RTRAVEL-13 봉쇄 보존&quot;">​</a></h3><p>막힌 연결은 지우지 않는다. 원인과 위험도와 복구 조건을 보여 준다.</p><h3 id="rtravel-14-조우-입력" tabindex="-1">RTRAVEL-14 조우 입력 <a class="header-anchor" href="#rtravel-14-조우-입력" aria-label="Permalink to &quot;RTRAVEL-14 조우 입력&quot;">​</a></h3><p>조우는 캠페인 시드와 위치와 시간과 소음과 세력 통제와 최근 사건과 파티 상태에서 결정된다. 입력을 빼 먹은 조우는 무효다.</p><h3 id="rtravel-15-동일-입력-동일-조우" tabindex="-1">RTRAVEL-15 동일 입력 동일 조우 <a class="header-anchor" href="#rtravel-15-동일-입력-동일-조우" aria-label="Permalink to &quot;RTRAVEL-15 동일 입력 동일 조우&quot;">​</a></h3><p>세계 상태와 명령이 같으면 같은 조우가 나와야 한다. 입력이 같은데 결과가 갈리면 규칙 위반이다.</p><h3 id="rtravel-16-비전투-해결" tabindex="-1">RTRAVEL-16 비전투 해결 <a class="header-anchor" href="#rtravel-16-비전투-해결" aria-label="Permalink to &quot;RTRAVEL-16 비전투 해결&quot;">​</a></h3><p>모든 조우가 전투로 이어지지 않는다. 통행료 지불과 교섭과 수리와 의료와 정보 제공과 은신과 우회가 정식 해결이다.</p><h2 id="판정-순서" tabindex="-1">판정 순서 <a class="header-anchor" href="#판정-순서" aria-label="Permalink to &quot;판정 순서&quot;">​</a></h2><ol><li>입력이 동서남북인지 확인한다.</li><li>대각선이면 행동을 깎지 않고 거부한다.</li><li>같은 격자에서 도착 칸을 읽는다.</li><li>기본 한 칸 비용에 층 전환을 더한다.</li><li>부상과 통증과 피로와 과적을 더한다.</li><li>어둠과 침수와 잔해와 화재를 더한다.</li><li>적대 통제와 통행권을 더한다.</li><li>파티 규모와 은밀 이동과 호위 대상을 더한다.</li><li>세계 지도의 노선과 환승과 봉쇄를 대조한다.</li><li>막힌 연결이면 원인과 위험도와 복구 조건을 유지한 채 보여 준다.</li><li>조우 입력을 시드부터 파티 상태까지 모은다.</li><li>동일 입력이면 동일 조우를 생성한다.</li><li>전투가 아니면 통행료와 교섭과 수리와 의료와 정보 제공과 은신과 우회로 해결한다.</li></ol><h2 id="금지-사항" tabindex="-1">금지 사항 <a class="header-anchor" href="#금지-사항" aria-label="Permalink to &quot;금지 사항&quot;">​</a></h2><ul><li>대각선 이동을 허용하는 일</li><li>대각선 거부에 행동을 깎는 일</li><li>탐색과 전투에 다른 격자를 쓰는 일</li><li>막힌 연결을 삭제하는 일</li><li>조우를 모두 전투로 처리하는 일</li><li>시드와 세계 상태가 같은데 다른 조우를 내는 일</li><li>원문에 없는 확률 숫자나 칸 비용을 규칙서에 적어 고정하는 일</li><li>통행료와 교섭과 수리와 의료와 정보 제공과 은신과 우회를 비공식 처리로 내리는 일</li><li>위치와 방향과 시야를 빼고 조우를 여는 일</li><li>세계 지도와 세부 격자를 다른 그래프로 쪼개는 일</li></ul><h2 id="출처" tabindex="-1">출처 <a class="header-anchor" href="#출처" aria-label="Permalink to &quot;출처&quot;">​</a></h2><ul><li><code>docs/game-logic/Travel-and-Encounters.md</code></li><li>원문은 허용 방향 4와 기본 한 칸 비용만 적었다.</li><li>조우 확률과 조건별 칸 비용의 고정 숫자는 원문에 없다.</li><li>구현 상수가 있으면 그 값을 우선한다.</li><li>UI 문서의 전투 격자 크기는 이동 계약이 아니라 채택하지 않았다.</li><li>잠긴 수치 충돌은 확인되지 않았다.</li></ul>',46)])])}const b=e(i,[["render",o]]);export{R as __pageData,b as default};
